/* Run this file in SQL Server Management Studio while connected to .\SQLEXPRESS. */
USE [master];
GO
IF DB_ID(N'GamifiedLearningSystem') IS NULL CREATE DATABASE [GamifiedLearningSystem];
GO
USE [GamifiedLearningSystem];
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
IF OBJECT_ID(N'dbo.Users',N'U') IS NULL CREATE TABLE dbo.Users (
 id varchar(36) NOT NULL PRIMARY KEY, email varchar(191) NOT NULL UNIQUE, passwordHash varchar(512) NOT NULL,
 role varchar(20) NOT NULL CONSTRAINT DF_Users_role DEFAULT 'STUDENT', createdAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(), updatedAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),
 CONSTRAINT CK_Users_role CHECK (role IN ('STUDENT','TEACHER','ADMIN')));
IF OBJECT_ID(N'dbo.Courses',N'U') IS NULL CREATE TABLE dbo.Courses (
 id varchar(36) NOT NULL PRIMARY KEY,title nvarchar(255) NOT NULL,description nvarchar(max) NOT NULL,category nvarchar(255) NOT NULL,imageUrl nvarchar(max) NOT NULL DEFAULT '',difficulty varchar(20) NOT NULL DEFAULT 'EASY',estimatedMinutes int NOT NULL,isPublished bit NOT NULL DEFAULT 0,createdByUserId varchar(36) NULL,createdAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),updatedAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),CONSTRAINT CK_Courses_difficulty CHECK (difficulty IN ('EASY','MEDIUM','HARD')));
IF OBJECT_ID(N'dbo.Students',N'U') IS NULL CREATE TABLE dbo.Students (
 id varchar(36) NOT NULL PRIMARY KEY,userId varchar(36) NOT NULL UNIQUE,firstName varchar(80) NOT NULL,lastName varchar(80) NOT NULL,avatarUrl nvarchar(1000) NOT NULL DEFAULT '',bio nvarchar(max) NOT NULL DEFAULT '',totalXP int NOT NULL DEFAULT 0,level int NOT NULL DEFAULT 1,currentStreak int NOT NULL DEFAULT 0,longestStreak int NOT NULL DEFAULT 0,lastActivityAt datetime2(3) NULL,version int NOT NULL DEFAULT 0,createdAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),updatedAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),CONSTRAINT FK_Students_Users FOREIGN KEY(userId) REFERENCES dbo.Users(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.Teachers',N'U') IS NULL CREATE TABLE dbo.Teachers (
 id varchar(36) NOT NULL PRIMARY KEY,userId varchar(36) NOT NULL UNIQUE,firstName varchar(80) NOT NULL,lastName varchar(80) NOT NULL,createdAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),CONSTRAINT FK_Teachers_Users FOREIGN KEY(userId) REFERENCES dbo.Users(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.CourseMaterials',N'U') IS NULL CREATE TABLE dbo.CourseMaterials (
 id varchar(36) NOT NULL PRIMARY KEY,courseId varchar(36) NOT NULL,title nvarchar(255) NOT NULL,content nvarchar(max) NOT NULL DEFAULT '',videoUrl nvarchar(1000) NOT NULL DEFAULT '',[order] int NOT NULL,createdAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),CONSTRAINT UQ_CourseMaterials_course_order UNIQUE(courseId,[order]),CONSTRAINT FK_CourseMaterials_Courses FOREIGN KEY(courseId) REFERENCES dbo.Courses(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.StudentMaterialProgress',N'U') IS NULL CREATE TABLE dbo.StudentMaterialProgress (
 studentId varchar(36) NOT NULL,materialId varchar(36) NOT NULL,completedAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),PRIMARY KEY(studentId,materialId),CONSTRAINT FK_StudentMaterialProgress_Students FOREIGN KEY(studentId) REFERENCES dbo.Students(id) ON DELETE CASCADE,CONSTRAINT FK_StudentMaterialProgress_Materials FOREIGN KEY(materialId) REFERENCES dbo.CourseMaterials(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.Levels',N'U') IS NULL CREATE TABLE dbo.Levels (
 id varchar(36) NOT NULL PRIMARY KEY,courseId varchar(36) NOT NULL,title nvarchar(255) NOT NULL,description nvarchar(max) NOT NULL,[order] int NOT NULL,requiredXP int NOT NULL DEFAULT 0,isLocked bit NOT NULL DEFAULT 0,createdAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),CONSTRAINT UQ_Levels_course_order UNIQUE(courseId,[order]),CONSTRAINT FK_Levels_Courses FOREIGN KEY(courseId) REFERENCES dbo.Courses(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.Topics',N'U') IS NULL CREATE TABLE dbo.Topics (
 id varchar(36) NOT NULL PRIMARY KEY,name nvarchar(255) NOT NULL,description nvarchar(max) NOT NULL,courseId varchar(36) NOT NULL,CONSTRAINT FK_Topics_Courses FOREIGN KEY(courseId) REFERENCES dbo.Courses(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.Tasks',N'U') IS NULL CREATE TABLE dbo.Tasks (
 id varchar(36) NOT NULL PRIMARY KEY,levelId varchar(36) NOT NULL,topicId varchar(36) NOT NULL,title nvarchar(255) NOT NULL,description nvarchar(max) NOT NULL,question nvarchar(max) NOT NULL,difficulty varchar(20) NOT NULL DEFAULT 'EASY',taskType varchar(30) NOT NULL DEFAULT 'MULTIPLE_CHOICE',xpReward int NOT NULL DEFAULT 100,timeLimit int NOT NULL DEFAULT 120,hint nvarchar(max) NOT NULL,correctAnswer nvarchar(1000) NOT NULL,explanation nvarchar(max) NOT NULL,[order] int NOT NULL,createdAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),updatedAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),CONSTRAINT UQ_Tasks_level_order UNIQUE(levelId,[order]),CONSTRAINT FK_Tasks_Levels FOREIGN KEY(levelId) REFERENCES dbo.Levels(id) ON DELETE CASCADE,CONSTRAINT FK_Tasks_Topics FOREIGN KEY(topicId) REFERENCES dbo.Topics(id),CONSTRAINT CK_Tasks_difficulty CHECK(difficulty IN ('EASY','MEDIUM','HARD')));
IF OBJECT_ID(N'dbo.TaskOptions',N'U') IS NULL CREATE TABLE dbo.TaskOptions (
 id varchar(36) NOT NULL PRIMARY KEY,taskId varchar(36) NOT NULL,[text] nvarchar(1000) NOT NULL,[order] int NOT NULL,CONSTRAINT UQ_TaskOptions_task_order UNIQUE(taskId,[order]),CONSTRAINT FK_TaskOptions_Tasks FOREIGN KEY(taskId) REFERENCES dbo.Tasks(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.Achievements',N'U') IS NULL CREATE TABLE dbo.Achievements (
 id varchar(36) NOT NULL PRIMARY KEY,code nvarchar(191) NOT NULL UNIQUE,title nvarchar(255) NOT NULL,description nvarchar(max) NOT NULL,icon nvarchar(255) NOT NULL,condition nvarchar(255) NOT NULL,target int NOT NULL,xpReward int NOT NULL DEFAULT 300);
IF OBJECT_ID(N'dbo.DailyGoals',N'U') IS NULL CREATE TABLE dbo.DailyGoals (id varchar(36) NOT NULL PRIMARY KEY,title nvarchar(255) NOT NULL,target int NOT NULL,xpReward int NOT NULL DEFAULT 200,isActive bit NOT NULL DEFAULT 1);
IF OBJECT_ID(N'dbo.Leaderboards',N'U') IS NULL CREATE TABLE dbo.Leaderboards (id varchar(36) NOT NULL PRIMARY KEY,name nvarchar(255) NOT NULL,period varchar(191) NOT NULL UNIQUE);
IF OBJECT_ID(N'dbo.Seasons',N'U') IS NULL CREATE TABLE dbo.Seasons (id varchar(36) NOT NULL PRIMARY KEY,title nvarchar(255) NOT NULL,description nvarchar(max) NOT NULL,startsAt datetime2(3) NOT NULL,endsAt datetime2(3) NOT NULL,rewards nvarchar(max) NOT NULL,finalizedAt datetime2(3) NULL);
IF OBJECT_ID(N'dbo.RefreshTokens',N'U') IS NULL CREATE TABLE dbo.RefreshTokens (id varchar(36) NOT NULL PRIMARY KEY,userId varchar(36) NOT NULL,tokenHash varchar(64) NOT NULL UNIQUE,expiresAt datetime2(3) NOT NULL,revokedAt datetime2(3) NULL,createdAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),CONSTRAINT FK_RefreshTokens_Users FOREIGN KEY(userId) REFERENCES dbo.Users(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.PasswordResetToken',N'U') IS NULL CREATE TABLE dbo.PasswordResetToken (id varchar(36) NOT NULL PRIMARY KEY,userId varchar(36) NOT NULL,tokenHash varchar(64) NOT NULL UNIQUE,expiresAt datetime2(3) NOT NULL,usedAt datetime2(3) NULL,CONSTRAINT FK_PasswordResetToken_Users FOREIGN KEY(userId) REFERENCES dbo.Users(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.TaskSession',N'U') IS NULL CREATE TABLE dbo.TaskSession (id varchar(36) NOT NULL PRIMARY KEY,studentId varchar(36) NOT NULL,taskId varchar(36) NOT NULL,startedAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),submittedAt datetime2(3) NULL,CONSTRAINT FK_TaskSession_Students FOREIGN KEY(studentId) REFERENCES dbo.Students(id) ON DELETE CASCADE,CONSTRAINT FK_TaskSession_Tasks FOREIGN KEY(taskId) REFERENCES dbo.Tasks(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.Attempts',N'U') IS NULL CREATE TABLE dbo.Attempts (id varchar(36) NOT NULL PRIMARY KEY,studentId varchar(36) NOT NULL,taskId varchar(36) NOT NULL,answer nvarchar(max) NOT NULL,isCorrect bit NOT NULL,score int NOT NULL,xpEarned int NOT NULL,timeSpent int NOT NULL,attemptNumber int NOT NULL,requestId varchar(36) NOT NULL,result nvarchar(max) NOT NULL,createdAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),CONSTRAINT UQ_Attempts_request UNIQUE(studentId,requestId),CONSTRAINT UQ_Attempts_number UNIQUE(studentId,taskId,attemptNumber),CONSTRAINT FK_Attempts_Students FOREIGN KEY(studentId) REFERENCES dbo.Students(id) ON DELETE CASCADE,CONSTRAINT FK_Attempts_Tasks FOREIGN KEY(taskId) REFERENCES dbo.Tasks(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.XpEvents',N'U') IS NULL CREATE TABLE dbo.XpEvents (id varchar(36) NOT NULL PRIMARY KEY,studentId varchar(36) NOT NULL,amount int NOT NULL,source nvarchar(100) NOT NULL,sourceId nvarchar(191) NOT NULL,createdAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),CONSTRAINT UQ_XpEvents_source UNIQUE(studentId,source,sourceId),CONSTRAINT FK_XpEvents_Students FOREIGN KEY(studentId) REFERENCES dbo.Students(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.StudentAchievements',N'U') IS NULL CREATE TABLE dbo.StudentAchievements (studentId varchar(36) NOT NULL,achievementId varchar(36) NOT NULL,unlockedAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),PRIMARY KEY(studentId,achievementId),CONSTRAINT FK_StudentAchievements_Students FOREIGN KEY(studentId) REFERENCES dbo.Students(id) ON DELETE CASCADE,CONSTRAINT FK_StudentAchievements_Achievements FOREIGN KEY(achievementId) REFERENCES dbo.Achievements(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.LeaderboardEntries',N'U') IS NULL CREATE TABLE dbo.LeaderboardEntries (leaderboardId varchar(36) NOT NULL,studentId varchar(36) NOT NULL,xp int NOT NULL DEFAULT 0,updatedAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),PRIMARY KEY(leaderboardId,studentId),CONSTRAINT FK_LeaderboardEntries_Leaderboards FOREIGN KEY(leaderboardId) REFERENCES dbo.Leaderboards(id) ON DELETE CASCADE,CONSTRAINT FK_LeaderboardEntries_Students FOREIGN KEY(studentId) REFERENCES dbo.Students(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.StudentSeasons',N'U') IS NULL CREATE TABLE dbo.StudentSeasons (studentId varchar(36) NOT NULL,seasonId varchar(36) NOT NULL,xp int NOT NULL DEFAULT 0,finalRank int NULL,badge nvarchar(255) NULL,PRIMARY KEY(studentId,seasonId),CONSTRAINT FK_StudentSeasons_Students FOREIGN KEY(studentId) REFERENCES dbo.Students(id) ON DELETE CASCADE,CONSTRAINT FK_StudentSeasons_Seasons FOREIGN KEY(seasonId) REFERENCES dbo.Seasons(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.StudentDailyGoals',N'U') IS NULL CREATE TABLE dbo.StudentDailyGoals (studentId varchar(36) NOT NULL,dailyGoalId varchar(36) NOT NULL,[date] varchar(10) NOT NULL,progress int NOT NULL DEFAULT 0,completedAt datetime2(3) NULL,PRIMARY KEY(studentId,dailyGoalId,[date]),CONSTRAINT FK_StudentDailyGoals_Students FOREIGN KEY(studentId) REFERENCES dbo.Students(id) ON DELETE CASCADE,CONSTRAINT FK_StudentDailyGoals_DailyGoals FOREIGN KEY(dailyGoalId) REFERENCES dbo.DailyGoals(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.Streaks',N'U') IS NULL CREATE TABLE dbo.Streaks (studentId varchar(36) NOT NULL PRIMARY KEY,[current] int NOT NULL DEFAULT 0,longest int NOT NULL DEFAULT 0,lastDate varchar(10) NULL,CONSTRAINT FK_Streaks_Students FOREIGN KEY(studentId) REFERENCES dbo.Students(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.Hints',N'U') IS NULL CREATE TABLE dbo.Hints (id varchar(36) NOT NULL PRIMARY KEY,studentId varchar(36) NOT NULL,taskId varchar(36) NOT NULL,[text] nvarchar(max) NOT NULL,createdAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),CONSTRAINT FK_Hints_Students FOREIGN KEY(studentId) REFERENCES dbo.Students(id) ON DELETE CASCADE,CONSTRAINT FK_Hints_Tasks FOREIGN KEY(taskId) REFERENCES dbo.Tasks(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.Notifications',N'U') IS NULL CREATE TABLE dbo.Notifications (id varchar(36) NOT NULL PRIMARY KEY,studentId varchar(36) NOT NULL,title nvarchar(255) NOT NULL,message nvarchar(max) NOT NULL,readAt datetime2(3) NULL,createdAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),CONSTRAINT FK_Notifications_Students FOREIGN KEY(studentId) REFERENCES dbo.Students(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.StudentTopicProgress',N'U') IS NULL CREATE TABLE dbo.StudentTopicProgress (studentId varchar(36) NOT NULL,topicId varchar(36) NOT NULL,correct int NOT NULL DEFAULT 0,wrong int NOT NULL DEFAULT 0,PRIMARY KEY(studentId,topicId),CONSTRAINT FK_StudentTopicProgress_Students FOREIGN KEY(studentId) REFERENCES dbo.Students(id) ON DELETE CASCADE,CONSTRAINT FK_StudentTopicProgress_Topics FOREIGN KEY(topicId) REFERENCES dbo.Topics(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.AIRecommendations',N'U') IS NULL CREATE TABLE dbo.AIRecommendations (id varchar(36) NOT NULL PRIMARY KEY,studentId varchar(36) NOT NULL,taskId varchar(36) NOT NULL,reason nvarchar(max) NOT NULL,source nvarchar(100) NOT NULL,createdAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),CONSTRAINT FK_AIRecommendations_Students FOREIGN KEY(studentId) REFERENCES dbo.Students(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.TaskReport',N'U') IS NULL CREATE TABLE dbo.TaskReport (id varchar(36) NOT NULL PRIMARY KEY,studentId varchar(36) NOT NULL,taskId varchar(36) NOT NULL,message nvarchar(max) NOT NULL,createdAt datetime2(3) NOT NULL DEFAULT sysutcdatetime(),CONSTRAINT FK_TaskReport_Students FOREIGN KEY(studentId) REFERENCES dbo.Students(id) ON DELETE CASCADE,CONSTRAINT FK_TaskReport_Tasks FOREIGN KEY(taskId) REFERENCES dbo.Tasks(id) ON DELETE CASCADE);
IF OBJECT_ID(N'dbo.Setting',N'U') IS NULL CREATE TABLE dbo.Setting ([key] nvarchar(191) NOT NULL PRIMARY KEY,value nvarchar(max) NOT NULL);
GO
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Students_totalXP' AND object_id=OBJECT_ID('dbo.Students')) CREATE INDEX IX_Students_totalXP ON dbo.Students(totalXP);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Topics_courseId' AND object_id=OBJECT_ID('dbo.Topics')) CREATE INDEX IX_Topics_courseId ON dbo.Topics(courseId);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Tasks_topic_difficulty' AND object_id=OBJECT_ID('dbo.Tasks')) CREATE INDEX IX_Tasks_topic_difficulty ON dbo.Tasks(topicId,difficulty);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Attempts_student_created' AND object_id=OBJECT_ID('dbo.Attempts')) CREATE INDEX IX_Attempts_student_created ON dbo.Attempts(studentId,createdAt);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Attempts_taskId' AND object_id=OBJECT_ID('dbo.Attempts')) CREATE INDEX IX_Attempts_taskId ON dbo.Attempts(taskId);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_XpEvents_student_created' AND object_id=OBJECT_ID('dbo.XpEvents')) CREATE INDEX IX_XpEvents_student_created ON dbo.XpEvents(studentId,createdAt);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_LeaderboardEntries_xp' AND object_id=OBJECT_ID('dbo.LeaderboardEntries')) CREATE INDEX IX_LeaderboardEntries_xp ON dbo.LeaderboardEntries(xp);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Hints_student_task' AND object_id=OBJECT_ID('dbo.Hints')) CREATE INDEX IX_Hints_student_task ON dbo.Hints(studentId,taskId);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Notifications_student_created' AND object_id=OBJECT_ID('dbo.Notifications')) CREATE INDEX IX_Notifications_student_created ON dbo.Notifications(studentId,createdAt);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_AIRecommendations_student_created' AND object_id=OBJECT_ID('dbo.AIRecommendations')) CREATE INDEX IX_AIRecommendations_student_created ON dbo.AIRecommendations(studentId,createdAt);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_TaskSession_student_task' AND object_id=OBJECT_ID('dbo.TaskSession')) CREATE INDEX IX_TaskSession_student_task ON dbo.TaskSession(studentId,taskId);
GO
